VID.narration = {"look":{"bar":false},"scenes":[{"dur":7.616,"caps":[[0.5,6.67,"Lecture thirteen. Thread-level parallelism. How one computer does many jobs at once."]],"warp":[[0,0],[0.5,0.9],[7.616,4]]},{"dur":25.008,"caps":[[0.5,6.83,"Crumb & Co must tally a year of receipts before 7."],[7.08,11.01,"One worker, one by one, is too slow."],[11.26,18.79,"Parallelism works at the process, thread, instruction and data level."],[19.04,22.89,"This lecture: threads inside one machine."]],"warp":[[0,0],[0.5,0.4],[7.08,2.6],[11.26,4.4],[19.04,7.6],[25.008,11]]},{"dur":26.68,"caps":[[0.5,4.91,"Process-level: each process has its own memory."],[5.16,10.85,"Spawning a new process every time is expensive."],[11.1,14.63,"Thread-level: one process starts several threads."],[14.88,21.05,"Each runs on its own core; all share one memory."],[21.3,24.91,"The model built for multi-core processors."]],"warp":[[0,0],[0.5,0.4],[5.16,2.6],[11.1,5.4],[14.88,7.4],[21.3,10],[26.68,13]]},{"dur":28.328,"caps":[[0.5,8.03,"SISD: one instruction stream, one data stream."],[8.28,17.41,"SIMD: the same instruction on many processors, each with its own data."],[17.66,22.79,"MIMD: each processor has its own instructions and its own data."],[23.04,26.25,"Cores running separate threads work this way."]],"warp":[[0,0],[0.5,0.4],[8.28,3.6],[17.66,7.8],[23.04,11],[28.328,14]]},{"dur":20.039,"caps":[[0.5,4.75,"A thread: a stream of execution spawned by a process."],[5,10.29,"Threads share memory: global variables and open files."],[10.54,16.15,"Every thread can see the parent process's data."],[16.4,19.21,"Nothing has to be copied or sent first."]],"warp":[[0,0],[0.5,0.4],[5,3.4],[10.54,6.4],[16.4,8.6],[20.039,11]]},{"dur":26.61,"caps":[[0.5,7.95,"1 thread does all 12 blocks: 12 minutes, 3 cores idle."],[8.2,11.89,"2 threads, 6 blocks each: 6 minutes."],[12.14,18.23,"4 threads on 4 cores, 3 blocks each: 3 minutes."],[18.48,25.05,"Threads need a shared memory, so they stay on one node."]],"warp":[[0,0],[0.5,0.4],[8.2,3.6],[12.14,6.2],[18.48,9.4],[26.61,14]]},{"dur":21.687,"caps":[[0.5,5.95,"OpenMP: mark what to parallelise; the compiler adds the threads."],[6.2,12.05,"Fork: the master thread spawns worker threads."],[12.3,15.19,"Faster threads wait for the slowest."],[15.44,20.01,"Join: a sync point. Then the master carries on alone."]],"warp":[[0,0],[0.5,0.4],[6.2,3],[12.3,6.6],[15.44,8.4],[21.687,12]]},{"dur":23.336,"caps":[[0.5,7.63,"1 thread: load, tally, sort, tally, report: 16 minutes."],[7.88,12.45,"2 threads: each tally is forked and joined: 10 minutes."],[12.7,15.43,"4 threads: 7 minutes."],[15.68,21.45,"The 4 sequential minutes never shrink."]],"warp":[[0,0],[0.5,0.4],[7.88,3.8],[12.7,7],[15.68,10],[23.336,13]]},{"dur":26.773,"caps":[[0.5,5.55,"Distributed memory: each process sees only its own data."],[5.8,12.69,"A message needs a send and a matching receive."],[12.94,19.43,"Receive from the wrong sender: no match."],[19.68,25.13,"MPI is the standard library for this."]],"warp":[[0,0],[0.5,0.4],[5.8,3.8],[12.94,7.4],[19.68,10.2],[26.773,13]]},{"dur":26.773,"caps":[[0.5,7.07,"MPI_COMM_WORLD holds every process: ranks 0 to 11."],[7.32,13.41,"Split into groups of 3: each numbers its members 0, 1, 2."],[13.66,19.27,"Process 7: rank 7 in the world, rank 1 in group C."],[19.52,26.01,"A communicator has a context, a group, a size and ranks."]],"warp":[[0,0],[0.5,0.4],[7.32,3.4],[13.66,6.4],[19.52,8.8],[26.773,11]]},{"dur":18.529,"caps":[],"warp":[[0,0],[0.5,0.9],[5.48,2],[11.58,3.1],[18.529,9]]}]};
